        # Return mock data with some test values
        return {
            "values": [
                ["", "", ""],
                ["", "", "test_value"],
                ["", "", ""]
            ]
        }

class MockSpreadsheet:
    id = "mock_spreadsheet_id"

# Monkey patch the external dependencies
import gspread.utils
import gspread.urls

# Save original functions
original_absolute_range_name = gspread.utils.absolute_range_name
original_fill_gaps = gspread.utils.fill_gaps

# Patch functions
gspread.utils.absolute_range_name = lambda x, y=None: "mock_range"
gspread.utils.fill_gaps = lambda x: x

