    cell = worksheet.find("test_value")
    print(f"Find result: {cell}")
    if cell:
        print(f"Found cell at row {cell.row}, col {cell.col} with value '{cell.value}'")
    else:
        print("No cell found")
except Exception as e:
    print(f"Error in find: {e}")

# Test the findall method
try:
    cells = worksheet.findall("test_value")
    print(f"Findall result: {cells}")
    print(f"Found {len(cells)} cells")
    for cell in cells:
        print(f"  Cell at row {cell.row}, col {cell.col} with value '{cell.value}'")
except Exception as e:
    print(f"Error in findall: {e}")

# Restore original functions
gspread.utils.absolute_range_name = original_absolute_range_name
gspread.utils.fill_gaps = original_fill_gaps
EOF
